function spawnEnemy(){if(!G||G.roomDone)return;let bossRoom=!!G.boss;if(bossRoom&&G.enemies.length===0&&!G.boss.spawned){G.boss.spawned=true;return}if(G.roomKills+G.enemies.length>=G.roomTarget)return;let edge=Math.floor(rand(G)*4),x=edge===0?30:edge===1?W-30:40+rand(G)*(W-80),y=edge===2?30:edge===3?H-30:70+rand(G)*(H-120),kind=pick(G,['stalker','stalker','shooter','charger',regions[G.region].kind]);G.enemies.push({x,y,r:kind==='charger'?13:11,hp:kind==='stalker'?32:kind==='shooter'?26:38,max:kind==='stalker'?32:kind==='shooter'?26:38,speed:kind==='stalker'?55:kind==='shooter'?43:kind==='charger'?75:50,kind,attack:1+rand(G)*1.6,wind:0,hit:0,slow:0,burn:0,phase:0,angle:0});}
function startBoss(){let b=G.boss;G.enemies.push({x:W/2,y:135,r:29,hp:b.hp,max:b.max,speed:65,kind:'boss',attack:1.2,wind:0,hit:0,slow:0,burn:0,phase:0,angle:0})}
function fire(){if(!G||G.paused||G.player.fireCd>0)return;let p=G.player,w=weapons[G.weapon],s=getStats(),mx=mouse.x,my=mouse.y;if(touch.active){let nearest=G.enemies.reduce((a,e)=>!a||Math.hypot(e.x-p.x,e.y-p.y)<Math.hypot(a.x-p.x,a.y-p.y)?e:a,null);if(nearest){mx=nearest.x;my=nearest.y}}let angle=Math.atan2(my-p.y,mx-p.x);p.aim=angle;p.fireCd=w.rate/s.rate;let shots=w.shots+s.shots-1+(G.synergies.some(x=>x.name==='Chuva de Agulhas')&&G.kills%4===0?1:0);for(let i=0;i<shots;i++){let a=angle+(i-(shots-1)/2)*(w.spread+(shots>1?.035:0)),d=w.damage*s.damage*(1+Math.min(.8,p.combo*.012));let crit=rand(G)<s.crit;if(crit)d*=s.critDamage;G.shots.push({x:p.x+Math.cos(a)*15,y:p.y+Math.sin(a)*15,vx:Math.cos(a)*w.speed,vy:Math.sin(a)*w.speed,life:w.range*s.range/w.speed,damage:d,pierce:w.pierce+s.pierce,hit:[],crit,boomerang:w.boomerang,splash:w.splash?50:0,homing:w.homing||0})}p.ether=Math.min(100,p.ether+2);audioBeep(G.weapon===1?150:330,.035,G.weapon===1?'triangle':'sine',.012)}
function damageEnemy(e,damage,crit=false){if(!G)return;e.hp-=damage;e.hit=.13;G.particles.push({x:e.x,y:e.y,r:crit?7:4,life:.24,color:crit?'#eff4b6':regions[G.region].accent});G.player.combo++;G.player.comboT=1.5+(G.effects.combo?1:0);if(G.effects.burn)e.burn=2.2;if(G.effects.freeze)e.slow=Math.max(e.slow,.65);if(G.effects.chain&&rand(G)<.18){let other=G.enemies.find(t=>t!==e&&Math.hypot(t.x-e.x,t.y-e.y)<105);if(other){other.hp-=damage*.4;G.particles.push({x:(e.x+other.x)/2,y:(e.y+other.y)/2,r:3,life:.2,color:'#8bd7ca'})}}if(G.effects.lifesteal&&rand(G)<.06)G.player.hp=Math.min(G.player.maxhp,G.player.hp+1);if(e.hp<=0){G.kills++;G.roomKills++;G.player.ether=Math.min(100,G.player.ether+8);if(G.effects.healKill)G.player.hp=Math.min(G.player.maxhp,G.player.hp+G.effects.healKill);let val=1+(G.effects.gold||0);G.pickups.push({x:e.x,y:e.y,r:4,value:val,kind:'shard',life:15});for(let i=0;i<5;i++)G.particles.push({x:e.x,y:e.y,r:2+rand(G)*4,life:.3+rand(G)*.3,color:regions[G.region].accent});audioBeep(220,.07,'triangle',.018)}}
function playerHit(dmg){let p=G.player;if(p.inv>0)return;if(p.shield>0){p.shield=0;p.inv=.35;showToast('A casca de sal absorveu o golpe');return}let s=getStats();p.hp-=dmg*(1-s.ward);p.inv=.65;G.particles.push({x:p.x,y:p.y,r:28,life:.35,color:'#e78d80'});audioBeep(100,.16,'sawtooth',.025);if(p.hp<=0)endRun(false)}
function useDash(){if(!G||G.paused)return;let p=G.player,s=getStats();if(p.dashCd>0)return;let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0),dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(touch.active){dx=touch.x;dy=touch.y}if(!dx&&!dy){dx=Math.cos(p.aim);dy=Math.sin(p.aim)}let len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;p.x=clamp(p.x+dx*90,24,W-24);p.y=clamp(p.y+dy*90,45,H-24);p.inv=.28;p.dashCd=.8/s.dash;G.particles.push({x:p.x-dx*25,y:p.y-dy*25,r:23,life:.25,color:'#c7e65b'});if(G.effects.dashDamage)for(let e of G.enemies)if(Math.hypot(e.x-p.x,e.y-p.y)<55)damageEnemy(e,24);audioBeep(470,.09,'triangle')}
function useSkill(){if(!G||G.paused)return;let p=G.player;if(p.skillCd>0||p.ether<55)return;p.ether-=55;p.skillCd=2.5;let hero=G.hero;if(hero===0){for(let e of G.enemies){let d=Math.hypot(e.x-p.x,e.y-p.y);if(d<155){damageEnemy(e,45*(1+G.effects.damage*.08));let a=Math.atan2(e.y-p.y,e.x-p.x);e.x+=Math.cos(a)*45;e.y+=Math.sin(a)*45}}G.bullets=[];G.particles.push({x:p.x,y:p.y,r:155,life:.42,color:'#c7e65b'})}else if(hero===1){p.shield=1;p.inv=.7;G.particles.push({x:p.x,y:p.y,r:60,life:.5,color:'#e6d895'})}else if(hero===2){let a=p.aim;p.x=clamp(p.x+Math.cos(a)*125,22,W-22);p.y=clamp(p.y+Math.sin(a)*125,45,H-22);p.inv=.65;G.particles.push({x:p.x,y:p.y,r:75,life:.4,color:'#f4b181'});for(let e of G.enemies)if(Math.hypot(e.x-p.x,e.y-p.y)<55)damageEnemy(e,34)}else{let nearest=G.enemies.slice().sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(nearest)for(let i=0;i<3;i++)setTimeout(()=>{if(G&&G.enemies.includes(nearest))damageEnemy(nearest,18)},i*140);p.inv=.4}audioBeep(510,.2,'sine',.035);updateUI()}

