function update(dt){let p=G.player,s=getStats();p.fireCd-=dt;p.inv-=dt;p.dashCd-=dt;p.skillCd-=dt;p.comboT-=dt;if(p.comboT<=0)p.combo=0;p.hp=Math.min(p.maxhp,p.hp+G.effects.regen*.035*dt*60);let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0),dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(touch.active){dx=touch.x;dy=touch.y}let len=Math.hypot(dx,dy);if(len){p.x=clamp(p.x+dx/len*s.speed*dt,16,W-16);p.y=clamp(p.y+dy/len*s.speed*dt,36,H-16)}if(mouse.down||touch.active)fire();G.spawnTimer-=dt;if(G.spawnTimer<=0){spawnEnemy();G.spawnTimer=Math.max(.24,.8-G.region*.05)}for(const e of G.enemies){e.attack-=dt;e.hit-=dt;e.slow-=dt;e.burn-=dt;if(e.burn>0&&Math.random()<dt*3)e.hp-=2;let vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy)||1,a=Math.atan2(vy,vx);e.angle=a;let speed=e.speed*(e.slow>0?.55:1)*(G.effects.slow&&d<105?.82:1);if(e.kind==='shooter'){if(d>205){e.x+=vx/d*speed*dt;e.y+=vy/d*speed*dt}else if(d<155){e.x-=vx/d*speed*dt*.6;e.y-=vy/d*speed*dt*.6}if(e.attack<=0){e.attack=1.8;e.wind=.42; e.targetA=a}}else if(e.kind==='charger'){if(e.wind>0){e.wind-=dt;if(e.wind<=0){e.charge=.35;e.chargeA=a}}else if(e.charge>0){e.charge-=dt;e.x+=Math.cos(e.chargeA)*240*dt;e.y+=Math.sin(e.chargeA)*240*dt}else if(e.attack<=0){e.attack=2.1;e.wind=.55}else{e.x+=vx/d*speed*dt*.65;e.y+=vy/d*speed*dt*.65}}else if(e.kind==='boss'){if(e.hp<e.max*.5&&e.phase===0){e.phase=1;e.attack=.55;ui.bossPhase.textContent='FASE II';showToast('A maré mudou de direção.')}if(d>110){e.x+=vx/d*speed*dt*.6;e.y+=vy/d*speed*dt*.6}else{e.x-=vx/d*speed*dt*.25;e.y-=vy/d*speed*dt*.25}if(e.attack<=0){e.attack=e.phase?1.05:1.55;e.wind=.4;e.targetA=a;e.volley=(e.volley||0)+1}}else{e.x+=vx/d*speed*dt;e.y+=vy/d*speed*dt}if(e.wind>0){e.wind-=dt;if(e.wind<=0&&(e.kind==='shooter'||e.kind==='charger'||e.kind==='boss')){let n=e.kind==='boss'?7:e.kind==='shooter'?1:1,base=e.targetA||a;for(let i=0;i<n;i++){let aa=base+(n>1?(i-(n-1)/2)*.22:0),v=e.kind==='boss'?175:145;G.bullets.push({x:e.x,y:e.y,vx:Math.cos(aa)*v,vy:Math.sin(aa)*v,life:3,r:e.kind==='boss'?5:4})}if(e.kind==='charger')e.charge=.42}}if(d<e.r+p.r+3)playerHit(e.kind==='boss'?17:11);}
for(const b of G.bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(Math.hypot(b.x-p.x,b.y-p.y)<p.r+b.r)playerHit(9)}G.bullets=G.bullets.filter(b=>b.life>0&&b.x>-10&&b.x<W+10&&b.y>-10&&b.y<H+10);
let weapon=weapons[G.weapon];for(const q of G.shots){if(q.homing){let target=G.enemies.reduce((a,e)=>!a||Math.hypot(e.x-q.x,e.y-q.y)<Math.hypot(a.x-q.x,a.y-q.y)?e:a,null);if(target){let an=Math.atan2(target.y-q.y,target.x-q.x),sp=Math.hypot(q.vx,q.vy);q.vx+=(Math.cos(an)*sp-q.vx)*q.homing;q.vy+=(Math.sin(an)*sp-q.vy)*q.homing}}q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;if(q.boomerang&&q.life<.35){q.vx+=(p.x-q.x)*dt*2;q.vy+=(p.y-q.y)*dt*2}for(const e of G.enemies){if(q.hit.includes(e)||Math.hypot(q.x-e.x,q.y-e.y)>q.r+e.r+2)continue;q.hit.push(e);damageEnemy(e,q.damage,q.crit);if(q.splash)for(const other of G.enemies)if(other!==e&&Math.hypot(other.x-e.x,other.y-e.y)<q.splash)damageEnemy(other,q.damage*.42);if(q.pierce<=0)q.life=-1;else q.pierce--}}G.shots=G.shots.filter(q=>q.life>0&&q.x>-30&&q.x<W+30&&q.y>-30&&q.y<H+30);
G.enemies=G.enemies.filter(e=>{if(e.kind==='boss'&&G.boss)G.boss.hp=Math.max(0,e.hp);if(e.hp<=0){if(e.kind==='boss'){G.boss=null;G.roomKills=G.roomTarget}return false}return true});if(G.boss&&G.boss.spawned&&G.enemies.length===0&&G.boss.hp<=0){G.roomKills=G.roomTarget}
for(const it of G.pickups){let d=Math.hypot(p.x-it.x,p.y-it.y),mag=s.magnet;if(d<mag){it.x+=(p.x-it.x)*Math.min(1,dt*4);it.y+=(p.y-it.y)*Math.min(1,dt*4)}if(d<18){G.shards+=it.value;meta.shards+=it.value;it.life=0;persist();audioBeep(620,.035,'sine',.01)}it.life-=dt}G.pickups=G.pickups.filter(i=>i.life>0);
for(const q of G.particles)q.life-=dt;G.particles=G.particles.filter(q=>q.life>0);
if(G.effects.orb){G.orbit=(G.orbit||0)+dt*2.7;for(let i=0;i<s.orb;i++){let a=G.orbit+i*TAU/s.orb,x=p.x+Math.cos(a)*38,y=p.y+Math.sin(a)*38;for(let e of G.enemies)if(Math.hypot(x-e.x,y-e.y)<e.r+7&&Math.random()<dt*4)damageEnemy(e,11)}}
if(G.roomKills>=G.roomTarget&&G.enemies.length===0&&!G.roomDone){G.roomDone=true;setTimeout(()=>G&&G.roomDone&&rewardRoom(),450)}if(G.boss)updateUI();}

