function chooseRewards(){let picks=[];while(picks.length<3){let pool=catalog.filter(i=>!G.items.some(owned=>owned.name===i.name));let item=pick(G,pool);let r=rand(G);if(r<.012+G.effects.luck*.008)item={...item,tier:'LENDÁRIA'};else if(r<.08+G.effects.luck*.018)item={...item,tier:'ÉPICA'};else if(r<.3+G.effects.luck*.025)item={...item,tier:'RARA'};if(!picks.some(x=>x.name===item.name))picks.push(item)}return picks}
function rewardRoom(){if(!G||!G.roomDone)return;if(G.boss===null&&G.room%3===0){G.player.hp=Math.min(G.player.maxhp,G.player.hp+12);G.player.ether=Math.min(100,G.player.ether+24);if(G.region===5){endRun(true);return}G.region++;G.room++;if(G.region===1&&!meta.unlocked.includes(1)){meta.unlocked.push(1);showToast('O Vigia despertou no Santuário.')}if(G.region===3&&!meta.unlocked.includes(2)){meta.unlocked.push(2);showToast('A Fagulha encontrou sua própria sombra.')}if(G.region===4&&!meta.unlocked.includes(3)){meta.unlocked.push(3);showToast('O Eco se lembrou do segundo corpo.')}persist()}else G.room++;let picks=chooseRewards();let secret=rand(G)<.09+G.effects.luck*.015;let extra=secret?`<button class="choice-card" id="secretChoice"><span class="item-icon">☽</span><span class="rarity">SALA SECRETA · OCULTO</span><strong>Porta entre as ondas</strong><small>Troque 12 fragmentos por uma relíquia secreta.</small></button>`:'';showOverlay(`<div class="overlay-kicker">${secret?'UM SUSSURRO NA PAREDE':'SALA CONQUISTADA · RECOMPENSA'}</div><h1>${secret?'Algo ficou para trás.':'Escolha o que permanece.'}</h1><p>${secret?'A maré abriu uma passagem que não deveria existir.':'Cada relíquia altera sua expedição. Sinergias surgem quando ecos da mesma natureza se encontram.'}</p><div class="choice-grid">${picks.map((it,i)=>`<button class="choice-card" data-item="${i}"><span class="item-icon">${it.icon}</span><span class="rarity">${it.tier} · ${it.title}</span><strong>${it.name}</strong><small>${it.desc}</small></button>`).join('')}${extra}</div><div class="modal-actions"><button class="secondary-btn" id="skipReward">DEIXAR O ECO IR · CURAR 10</button></div>`, 'reward');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>takeReward(picks[+b.dataset.item]));$('#skipReward').onclick=()=>{G.player.hp=Math.min(G.player.maxhp,G.player.hp+10);continueRun()};if(secret)$('#secretChoice').onclick=()=>{if(meta.shards<12){showToast('São necessários 12 fragmentos.');return}meta.shards-=12;let rare=pick(G,catalog.filter(it=>it.tier==='LENDÁRIA'));takeReward({...rare,tier:'SECRETA',name:'Secreto: '+rare.name})}}
function takeReward(item){if(G.items.length<6){addItem(item);continueRun();return}showOverlay(`<div class="overlay-kicker">SEUS SEIS ESPAÇOS ESTÃO OCUPADOS</div><h1>Qual eco você solta?</h1><p>O novo fragmento precisa tomar o lugar de uma relíquia carregada.</p><div class="choice-grid">${G.items.map((it,i)=>`<button class="choice-card" data-drop="${i}"><span class="item-icon">${it.icon}</span><span class="rarity">SUBSTITUIR</span><strong>${it.name}</strong><small>${it.desc}</small></button>`).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="keepOld">FICAR COM AS ANTIGAS</button></div>`, 'replace');document.querySelectorAll('[data-drop]').forEach(b=>b.onclick=()=>{let old=G.items.splice(+b.dataset.drop,1)[0];G.effects[old.effect]=Math.max(0,G.effects[old.effect]-old.power);addItem(item);continueRun()});$('#keepOld').onclick=continueRun}
