ctx.save();ctx.globalAlpha=.14;ctx.strokeStyle=r.accent;for(let i=0;i<7;i++){let x=(i*159+time*8)%W;ctx.beginPath();ctx.moveTo(x,42);ctx.lineTo(x+Math.sin(time+i)*4,H-18);ctx.stroke()}ctx.restore();
