for(const q of G.shots){ctx.fillStyle=q.crit?'#fff5b0':r.accent;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=q.crit?12:5;ctx.beginPath();ctx.arc(q.x,q.y,q.crit?4:3,0,TAU);ctx.fill();ctx.shadowBlur=0}for(const b of G.bullets){ctx.fillStyle='#e99c88';ctx.shadowColor='#e99c88';ctx.shadowBlur=8;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,TAU);ctx.fill();ctx.shadowBlur=0}
for(const e of G.enemies){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle||0);let boss=e.kind==='boss',radius=e.r,base=e.hit>0?'#fff2c2':boss?r.accent:e.kind==='shooter'?'#d18b94':e.kind==='charger'?'#e1a56f':'#a7c77b';ctx.shadowColor=base;ctx.shadowBlur=boss?22:9;ctx.fillStyle=base;ctx.strokeStyle='#18211d';ctx.lineWidth=2;ctx.beginPath();if(e.kind==='shooter'){ctx.moveTo(radius,0);ctx.lineTo(0,radius);ctx.lineTo(-radius,0);ctx.lineTo(0,-radius)}else if(e.kind==='boss'){for(let i=0;i<8;i++){let a=i*TAU/8,rr=i%2?radius*.82:radius;ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}}else{ctx.arc(0,0,radius,0,TAU)}ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#17211c';ctx.beginPath();ctx.arc(3,-2,boss?4:2.5,0,TAU);ctx.fill();ctx.restore();if(e.kind==='boss'){ctx.fillStyle='#101713';ctx.fillRect(e.x-32,e.y-40,64,3);ctx.fillStyle=r.accent;ctx.fillRect(e.x-32,e.y-40,64*e.hp/e.max,3)}else if(e.hp<e.max){ctx.fillStyle='#141b16';ctx.fillRect(e.x-10,e.y-e.r-8,20,2);ctx.fillStyle='#d4e49a';ctx.fillRect(e.x-10,e.y-e.r-8,20*e.hp/e.max,2)}}
if(G.effects.orb){for(let i=0;i<G.effects.orb+(G.synergies.some(x=>x.name==='Pequeno Sistema')?1:0);i++){let n=G.effects.orb+(G.synergies.some(x=>x.name==='Pequeno Sistema')?1:0),a=(G.orbit||0)+i*TAU/n;ctx.fillStyle='#e7e7b4';ctx.beginPath();ctx.arc(G.player.x+Math.cos(a)*38,G.player.y+Math.sin(a)*38,5,0,TAU);ctx.fill()}}
let p=G.player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.aim);if(p.inv>0&&Math.floor(time*24)%2===0)ctx.globalAlpha=.42;ctx.shadowColor=heroes[G.hero].color;ctx.shadowBlur=18;ctx.fillStyle=heroes[G.hero].color;ctx.strokeStyle='#17201a';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,p.r,0,TAU);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#273020';ctx.beginPath();ctx.moveTo(4,-4);ctx.lineTo(15,0);ctx.lineTo(4,4);ctx.closePath();ctx.fill();if(p.shield){ctx.strokeStyle='#eadb9d';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,22,0,TAU);ctx.stroke()}ctx.restore();
for(const q of G.particles){ctx.globalAlpha=clamp(q.life*2,0,1);ctx.strokeStyle=q.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(q.x,q.y,q.r*(1+(1-q.life)),0,TAU);ctx.stroke();ctx.globalAlpha=1}
let accent=r.accent;ctx.fillStyle='#1017138c';ctx.fillRect(22,H-22,140,4);ctx.fillStyle=accent;ctx.fillRect(22,H-22,140*clamp(p.hp/p.maxhp,0,1),4);ctx.restore()}
function loop(now){if(!G)return;let dt=Math.min(.033,(now-last)/1000||0);last=now;if(!G.paused){update(dt);draw()}raf=requestAnimationFrame(loop)}

