function showMenu(){let unlocked=meta.unlocked.map(i=>heroes[i]);showOverlay(`<div class="overlay-kicker">UM ROGUELIKE SOBRE MEMÓRIA E MARÉS</div><h1>O mundo esquece.<span>Você, não.</span></h1><p>Quando a realidade recua, só restam ecos. Atravesse seis regiões que se reescrevem, reúna relíquias impossíveis e descubra por que o mundo insiste em terminar.</p><div class="hero-options">${heroes.map((h,i)=>`<button class="hero-option ${meta.unlocked.includes(i)?'':'locked'} ${selectedHero===i?'selected':''}" data-hero="${i}" ${meta.unlocked.includes(i)?'':'disabled'}><strong>${h.icon} &nbsp;${h.name}${meta.unlocked.includes(i)?'':' · BLOQUEADO'}</strong><small>${h.desc}</small></button>`).join('')}</div><button class="primary-btn" id="startRun">INICIAR EXPEDIÇÃO &nbsp; ↗</button><div class="overlay-kicker" style="margin-top:15px;color:#aab39c">WASD mover · mouse mirar · clique atacar · espaço esquivar · Q habilidade</div>`, 'menu');$('#startRun').onclick=()=>startRun();document.querySelectorAll('.hero-option:not(.locked)').forEach(button=>button.onclick=()=>setSelectedHero(+button.dataset.hero))}
