 function sanctuary(){let costs={vitality:12,force:15,echo:10},labels={vitality:'VITALIDADE · +8 vida inicial',force:'FORÇA · +7% dano',echo:'ECO · +1 fragmento por abate'};showOverlay(`<div class="overlay-kicker">SANTUÁRIO · PROGRESSO PERMANENTE</div><h1>O que a memória guarda.</h1><p>Fragmentos disponíveis: <b>${meta.shards}</b>. Melhor expedição: <b>${meta.best}</b> ecos · Vitórias: <b>${meta.clears}</b>.</p><div class="sanctuary-list">${Object.keys(costs).map(key=>`<div class="upgrade-row"><span><b>${labels[key]}</b><small>Nível ${meta.upgrades[key]||0} · Custo ${costs[key]+(meta.upgrades[key]||0)*8} fragmentos</small></span><button class="secondary-btn" data-upgrade="${key}">APRIMORAR</button></div>`).join('')}</div><button class="primary-btn" id="sanctuaryBack">${G?'VOLTAR À EXPEDIÇÃO':'VOLTAR AO MENU'}</button>`, 'sanctuary');document.querySelectorAll('[data-upgrade]').forEach(button=>button.onclick=()=>{let key=button.dataset.upgrade,cost=costs[key]+(meta.upgrades[key]||0)*8;if(meta.shards<cost){showToast('Ainda faltam fragmentos de memória.');return}meta.shards-=cost;meta.upgrades[key]=(meta.upgrades[key]||0)+1;persist();sanctuary()});$('#sanctuaryBack').onclick=()=>G?hideOverlay():showMenu()}
