 function showHeroPicker(){showOverlay(`<div class="overlay-kicker">PRÓXIMA EXPEDIÇÃO</div><h1>Escolha quem lembrará.</h1><p>A mudança vale para a próxima expedição. Personagem selecionado: <b>${heroes[selectedHero].name}</b>.</p><div class="hero-options">${heroes.map((h,i)=>`<button class="hero-option ${meta.unlocked.includes(i)?'':'locked'} ${selectedHero===i?'selected':''}" data-hero="${i}" ${meta.unlocked.includes(i)?'':'disabled'}><strong>${h.icon} &nbsp;${h.name}</strong><small>${h.desc}</small></button>`).join('')}</div><button class="primary-btn" id="heroClose">VOLTAR</button>`, 'hero');document.querySelectorAll('.hero-option:not(.locked)').forEach(button=>button.onclick=()=>{setSelectedHero(+button.dataset.hero);showHeroPicker()});$('#heroClose').onclick=hideOverlay}
 function bind(){canvas.addEventListener('pointermove',event=>{let point=canvasPoint(event);mouse.x=point.x;mouse.y=point.y});canvas.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'&&event.button!==0)return;let point=canvasPoint(event);mouse.x=point.x;mouse.y=point.y;mouse.down=true;canvas.setPointerCapture?.(event.pointerId)});canvas.addEventListener('pointerup',()=>mouse.down=false);canvas.addEventListener('pointercancel',()=>mouse.down=false);window.addEventListener('keydown',event=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.code))event.preventDefault();keys[event.code]=true;if(event.repeat)return;if(event.code==='Space')useDash();if(event.code==='KeyQ')useSkill();if(event.code==='Escape'){if(G&&!G.paused)showPause();else if(G&&overlayMode==='pause')hideOverlay()}});window.addEventListener('keyup',event=>{keys[event.code]=false});$('#pauseBtn').onclick=()=>G?(G.paused?hideOverlay():showPause()):showMenu();$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').classList.toggle('active',soundOn);showToast(soundOn?'Som ativado':'Som desativado');if(soundOn)audioBeep(440)};$('#helpBtn').onclick=showHelp;$('#metaBtn').onclick=sanctuary;$('#heroBtn').onclick=showHeroPicker;$('#weaponBtn').onclick=()=>{if(!G)return;G.weapon=(G.weapon+1)%weapons.length;updateUI();showToast(`Arma: ${weapons[G.weapon].name}`)};$('#touchDash').addEventListener('pointerdown',event=>{event.preventDefault();useDash()});$('#touchSkill').addEventListener('pointerdown',event=>{event.preventDefault();useSkill()});let stick=$('#stick'),stickPointer=null;stick.addEventListener('pointerdown',event=>{event.preventDefault();stickPointer=event.pointerId;stick.setPointerCapture(event.pointerId);touch.active=true;moveStick(event)});stick.addEventListener('pointermove',event=>{if(event.pointerId===stickPointer)moveStick(event)});let release=event=>{if(event.pointerId!==stickPointer)return;stickPointer=null;touch.active=false;touch.x=touch.y=0;stick.style.setProperty('--stick-x','0px');stick.style.setProperty('--stick-y','0px')};stick.addEventListener('pointerup',release);stick.addEventListener('pointercancel',release);function moveStick(event){let rect=stick.getBoundingClientRect(),dx=event.clientX-(rect.left+rect.width/2),dy=event.clientY-(rect.top+rect.height/2),len=Math.hypot(dx,dy),scale=len>42?42/len:1;touch.x=dx*scale/42;touch.y=dy*scale/42;stick.style.setProperty('--stick-x',`${dx*scale}px`);stick.style.setProperty('--stick-y',`${dy*scale}px`)}document.addEventListener('visibilitychange',()=>{if(document.hidden&&G&&!G.paused)showPause()})}
